// Turn the raw ideas rows into one item per category.
//
// Deliberately derived from the live table rather than from a hardcoded list
// of 14 slugs: categories will be added, and a pipeline that has to be edited
// every time one appears is a pipeline that silently goes stale.
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) {
  throw new Error('No completed ideas came back from Supabase. Check the filter and the credential.');
}

const byCat = new Map();
for (const r of rows) {
  if (!r.category_slug) continue;
  let c = byCat.get(r.category_slug);
  if (!c) {
    c = { category_slug: r.category_slug, category_name: r.category_name, idea_count: 0, titles: [] };
    byCat.set(r.category_slug, c);
  }
  c.idea_count += 1;
  if (c.titles.length < 12 && r.title) c.titles.push(r.title);
}

// Optional narrowing: set ONLY_CATEGORY in the n8n environment to run a
// single category first and read the output before spending keys on all 14.
const only = $env.ONLY_CATEGORY;

return [...byCat.values()]
  .filter((c) => !only || c.category_slug === only)
  .map((c) => ({
    json: {
      category_slug: c.category_slug,
      category_name: c.category_name,
      idea_count: c.idea_count,
      sample_titles: c.titles.map((t) => `- ${t}`).join('\n'),
    },
  }));

// Parse Gemini's JSON array into one n8n item per FAQ, so the Supabase node
// inserts twelve rows rather than one row holding an array.
//
// Every check below rejects the whole batch for that category rather than
// writing partial or malformed content. A bad row in this table shows up on
// a public page, and the site has already had to strip invented content four
// separate times.
const BANNED_VENDORS = /\b(claude|perplexity|chatgpt|openai|grok|gemini|copilot)\b/i;
const YEAR = /\b(19|20)\d{2}\b/;
const EMOJI = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/u;

const out = [];

for (const item of $input.all()) {
  const cat = $('Distinct Categories').item.json;

  let raw = item.json.text ?? item.json.output ?? item.json.candidates?.[0]?.content?.parts?.[0]?.text;
  if (typeof raw !== 'string') {
    throw new Error(`No text back from Gemini for ${cat.category_slug}. Full response: ${JSON.stringify(item.json).slice(0, 500)}`);
  }

  // Strip fences if the model added them despite being told not to.
  raw = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`Gemini returned non-JSON for ${cat.category_slug}: ${raw.slice(0, 300)}`);
  }

  if (!Array.isArray(parsed)) throw new Error(`Expected an array for ${cat.category_slug}, got ${typeof parsed}`);
  if (parsed.length < 8) throw new Error(`Only ${parsed.length} FAQs for ${cat.category_slug}; expected 12. Not writing a thin pool.`);

  const seen = new Set();

  for (const row of parsed) {
    const q = String(row.question ?? '').trim();
    const a = String(row.answer ?? '').trim();

    if (!q || !a) throw new Error(`Empty question or answer in ${cat.category_slug}`);
    if (BANNED_VENDORS.test(q) || BANNED_VENDORS.test(a)) {
      throw new Error(`Named an AI vendor in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    if (YEAR.test(q) || YEAR.test(a)) {
      throw new Error(`Contains a year in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    if (EMOJI.test(q) || EMOJI.test(a)) {
      throw new Error(`Contains an emoji in ${cat.category_slug}: ${q.slice(0, 80)}`);
    }
    const wordCount = a.split(/\s+/).length;
    if (wordCount < 25 || wordCount > 130) {
      throw new Error(`Answer is ${wordCount} words in ${cat.category_slug}; wanted 40-90. Q: ${q.slice(0, 60)}`);
    }
    const key = q.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (seen.has(key)) throw new Error(`Duplicate question inside ${cat.category_slug}: ${q.slice(0, 80)}`);
    seen.add(key);

    out.push({ json: { category_slug: cat.category_slug, question: q, answer: a, is_active: true } });
  }
}

return out;
